{
  struct sockaddr_un sun;
  char *path;
  int fd;
  size_t path_len;
  ssize_t sun_len;

  fd = socket (AF_UNIX, SOCK_STREAM, 0);
  if (fd < 0)
    {
      perror ("socket");
      return -1;
    }

  path = create_socket_name ("fep-XXXXXX/control");
  if (path == NULL)
    {
      close (fd);
      return -1;
    }

  path_len = strlen (path);
  if (path_len + 1 >= sizeof(sun.sun_path))
    {
      fep_log (FEP_LOG_LEVEL_WARNING,
	       "unix domain socket path too long: %zu + 1 >= %zu",
	       path_len,
	       sizeof (sun.sun_path));
      free (path);
      close (fd);
      return -1;
    }

  memset (&sun, 0, sizeof(sun));
  sun.sun_family = AF_UNIX;

#ifdef __linux__
  sun.sun_path[0] = '\0';
  memcpy (sun.sun_path + 1, path, path_len);
  sun_len = offsetof (struct sockaddr_un, sun_path) + path_len + 1;
  remove_control_socket (path);
#else
  memcpy (sun.sun_path, path, path_len);
  sun_len = sizeof (struct sockaddr_un);
#endif

  if (bind (fd, (const struct sockaddr *) &sun, sun_len) < 0)
    {
      perror ("bind");
      free (path);
      close (fd);
      return -1;
    }

  if (listen (fd, 5) < 0)
    {
      perror ("listen");
      free (path);
      close (fd);
      return -1;
    }

  fep->server = fd;
  fep->control_socket_path = path;
  return 0;
}

